using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
// Portable, read-only import/reference verification. Run with -executeMethod PublicSnapshotChecks.Verify.
public static class PublicSnapshotChecks {
 public static void Verify(){var rows=new List<string>();string scenePath="Assets/Scenes/CombatFormulaComparison.unity";var scene=EditorSceneManager.OpenScene(scenePath);var actors=new List<TrainingFighter>();foreach(var root in scene.GetRootGameObjects())foreach(var c in root.GetComponentsInChildren<Component>(true)){if(c==null)throw new Exception("Missing component in playable scene");if(c is TrainingFighter f)actors.Add(f);if(c is Collider old&&old.enabled)throw new Exception("Enabled legacy3D collider");}if(actors.Count!=2)throw new Exception("Expected two fighters");foreach(var f in actors){if(f.GetComponent<TrainingMotor2D>()==null||f.GetComponent<Rigidbody2D>()==null||f.GetComponent<CharacterController>()!=null)throw new Exception("Invalid native2D body");var v=f.GetComponent<ArmoredStaticPoseView>();if(v==null||v.image==null||v.characterProfile==null||!v.characterProfile.Valid)throw new Exception("Missing approved presentation");if(f.definition==null)throw new Exception("Missing character definition");var tuning=f.GetComponent<ApprovedLocomotionTuning>();if(tuning!=null&&!MotionProfileAdoption.ValidateBuildTarget(tuning,out var why))throw new Exception(why);rows.Add("PASS body, sprites, persistent locomotion: "+f.name);}
 var combat=actors.Select(x=>x.GetComponent<CombatTestV01>()).FirstOrDefault(x=>x!=null);if(combat==null)throw new Exception("Missing combat session");var profile=combat.profile;if(profile==null||!profile.Validate(out var error))throw new Exception("Invalid combat profile");rows.Add("PASS combat profile");if(!EditorBuildSettings.scenes.Any(x=>x.enabled&&x.path==scenePath))throw new Exception("Playable build scene missing");rows.Add("PASS build scene");
 foreach(var dep in AssetDatabase.GetDependencies(scenePath,true)){if(dep.EndsWith(".vrm",StringComparison.OrdinalIgnoreCase)||dep.EndsWith(".fbx",StringComparison.OrdinalIgnoreCase)||dep.Contains("com.vrmc."))throw new Exception("Forbidden old model dependency: "+dep);if(dep.StartsWith("Packages/")){if(AssetDatabase.LoadMainAssetAtPath(dep)==null)throw new Exception("Missing registry asset: "+dep);}else if(!File.Exists(dep))throw new Exception("Missing dependency: "+dep);}rows.Add("PASS playable dependency closure");var author=EditorSceneManager.OpenScene("Assets/Scenes/MoveSpatialAuthoring.unity");if(UnityEngine.Object.FindAnyObjectByType<TrainingSpatialAuthoring>()==null)throw new Exception("Missing authoring host");foreach(var root in author.GetRootGameObjects())foreach(var c in root.GetComponentsInChildren<Component>(true))if(c==null)throw new Exception("Missing authoring component");rows.Add("PASS editing scene");rows.Add(CombatV01FormulaChecks.Run());EditorSceneManager.OpenScene(scenePath);rows.Add("PASS public snapshot import/reference verification");var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-publicationReport");if(i>=0&&i+1<args.Length)File.WriteAllLines(args[i+1],rows);Debug.Log(string.Join("\n",rows));}
}
